/-- Bounded positive covariate density. -/
def BoundedPositiveCovDensity {d : ℕ} (P : OutcomeLaw d) : Prop :=
  ∃ lower upper : ℝ, CovDensityBounds P lower upper

/-- Normalized Fourier coefficients of the reflected function. -/
def Fhat (m : Cube d → ℝ) (k : Fin d → ℤ) : ℂ :=
  ∫ y, ek (-k) y * reflExt m y ∂torusMeasure d

/-- Finite second moments of both potential outcomes. -/
def FiniteOutcomeMoments {d : ℕ} (P : OutcomeLaw d) : Prop :=
  MemLp (fun ω => ω.2.1) 2 P.toMeasure ∧ MemLp (fun ω => ω.2.2) 2 P.toMeasure

/-- Pair-cosine indices and positive integer frequencies. -/
abbrev PairIdx (d L : ℕ) :=
  {α : (Fin d × Fin d) × (Fin L × Fin L) // α.1.1 < α.1.2}

/-- Pointwise fairness, used internally for concrete constructions and the cited carrier. -/
def PointwiseFairKernel (π : Kernel (Covariates n d) (Signs n)) : Prop :=
  ∀ x i, ∫ z, sgn (z i) ∂π x = 0

/-- Independent uniform covariates on an arbitrary sampling space. -/
def UniformDraw (μ : Measure Ω) (X : Ω → Covariates n d) : Prop :=
  Measurable X ∧ μ.map X = covLaw n d

/-- Active coordinates in increasing original-unit order. -/
def activeIndices (u : Fin n → ℝ) : List (Fin n) :=
  (List.finRange n).filter (fun i => decide (|u i| < 1))

/-- Restrict a vector to active coordinates. -/
def activeMask (u v : Fin n → ℝ) : Fin n → ℝ :=
  fun i => if |u i| < 1 then v i else 0

/-- Lower comparison scale. -/
def bScale (n d : ℕ) (s : ℝ) : ℝ :=
  min 1 (((pairCount d : ℝ) / n) ^ s) -- @realizes b_s(min 1 (B/n)^s)

