∀ {n : ℕ} {Ω : Type u_1} [inst : MeasurableSpace Ω] (cs : List (Ω → Fin n → ℝ)) (u : Ω → Fin n → ℝ) (t₁ t₂ : Ω → ℝ),
  (∀ c ∈ cs, Measurable c) →
    Measurable u →
      Measurable t₁ →
        Measurable t₂ →
          Measurable fun x =>
            have bs := List.map (fun c => c x) cs;
            have ws := List.map (fun v => (CausalSmith.Experimentation.BivariateSobolevDesignCapacity.boundaryPlus (u x) v * CausalSmith.Experimentation.BivariateSobolevDesignCapacity.boundaryMinus (u x) v)⁻¹) bs;
            have v := CausalSmith.Experimentation.BivariateSobolevDesignCapacity.inverseCDF (bs.zip (List.map (fun w => w / ws.sum) ws)) (t₁ x);
            if t₂ x < CausalSmith.Experimentation.BivariateSobolevDesignCapacity.boundaryMinus (u x) v / (CausalSmith.Experimentation.BivariateSobolevDesignCapacity.boundaryPlus (u x) v + CausalSmith.Experimentation.BivariateSobolevDesignCapacity.boundaryMinus (u x) v) then u x + CausalSmith.Experimentation.BivariateSobolevDesignCapacity.boundaryPlus (u x) v • v else u x - CausalSmith.Experimentation.BivariateSobolevDesignCapacity.boundaryMinus (u x) v • v

