/-- The positive boundary-hit distance along a nonzero active direction. -/
def boundaryPlus (u v : Fin n → ℝ) : ℝ :=
  finiteMin ((activeIndices u).filterMap (fun i =>
    if 0 < v i then some ((1 - u i) / v i)
    else if v i < 0 then some ((1 + u i) / (-v i)) else none))

/-- [ The larger published correctly specified class, with intercepts and a prognostic L² bound. -/
def boundedDensityClass (d : ℕ) (s lower upper : ℝ) : Set (OutcomeLaw d) :=
  {P | CovDensityBounds P lower upper ∧ FiniteOutcomeMoments P ∧
    (∫ u, prognosisOf P u ^ 2 ∂covMarginal P) ≤ 1 ∧
    ∃ (intercept : ℝ) (m : CenteredL2Fn d), SobolevClass d s m ∧
      prognosisOf P =ᵐ[cubeMeasure d] fun u => intercept + m.val u}

/-- Sharper lower constant, independent of n and d. -/
def cLower (s : ℝ) : ℝ :=
  2 / ((48 + 32 * Real.pi ^ 2) * (16384 : ℝ) ^ s)

/-- [ The piecewise affine cutoff with plateau [0,1] and support [-1,2]. -/
-- @node: cosineCutoff
def cosineCutoff (u : ℝ) : ℝ := max 0 (min 1 (min (u + 1) (2 - u)))

/-- Uniform independent coefficient signs; its function image is the legal-prior candidate. -/
def cosinePrior (n d : ℕ) (_s : ℝ) : PMF (PairIdx d (priorCutoff n d) → Bool) :=
  PMF.uniformOfFintype _ -- @realizes xi(uniform coefficient signs independent of X)

/-- Independent uniform original covariates. -/
def covLaw (n d : ℕ) : Measure (Covariates n d) :=
  Measure.pi (fun _ => cubeMeasure d)

/-- Product uniform measure, including the zero-dimensional convention. -/
def cubeMeasure (d : ℕ) : Measure (Cube d) :=
  Measure.pi (fun _ => volume.restrict (Icc (0 : ℝ) 1))

/-- Conditional mean treatment effect. -/
def effectOf {d : ℕ} (P : OutcomeLaw d) (u : Cube d) : ℝ :=
  ∫ y, y.2 - y.1 ∂P.toMeasure.condKernel u

/-- The closed unit cube in Euclidean coordinates. -/
def euclideanCube (p : ℕ) : Set (EuclideanSpace ℝ (Fin p)) :=
  {u | ∀ h, u h ∈ Icc (0 : ℝ) 1} -- @realizes p(component dimensions 1 or 2 at consumers)

/-- [ The even reflected slice on the period-two representative interval. -/
-- @node: evenReflectionSlice
def evenReflectionSlice (f : ℝ → ℂ) (y : ℝ) : ℂ :=
  if y ≤ 1 then f y else f (2 - y)

/-- [ Nonnegative carrier of the actual law-specific excess, not a surrogate imbalance risk. -/
def excess {n d : ℕ} (π : Design n d) (P : OutcomeLaw d) : ℝ≥0∞ :=
  ENNReal.ofReal (publishedExcessReal π P)

/-- The index-th frequency in the prescribed ordering; a box of radius index+1 suffices. -/
def featureFrequency (d index : ℕ) : Fin d → ℤ :=
  (orderedFrequencyBox d (index + 1)).getD index 0

/-- Consecutive real cosine/sine pairs, with row numbering starting at one. -/
def features (d h : ℕ) (y : Torus d) : ℝ :=
  let k := featureFrequency d ((h - 1) / 2)
  if (h - 1) % 2 = 0 then Real.sqrt 2 * (ek k y).re else Real.sqrt 2 * (ek k y).im

/-- Realized full-schedule finite-population ATE. -/
def finiteATE (y : Sched n) : ℝ :=
  (n : ℝ)⁻¹ * ∑ i, ((y i).2 - (y i).1) -- @realizes theta_n(full-schedule average effect)

/-- Increasing finite integer frequency boxes. -/
def frequencyBox (r J : ℕ) : Finset (Fin r → ℤ) :=
  Fintype.piFinset (fun _ => Finset.Icc (-(J : ℤ)) (J : ℤ))

/-- Complexity of a nonzero frequency, with the harmless value zero at frequency zero. -/
def frequencyComplexity (k : Fin d → ℤ) : ℝ :=
  frequencySq k / (frequencySupport k).card -- @realizes t(||k||²/|supp k|)

/-- Integer frequencies with their actual nonzero coordinate support. -/
def frequencySupport (k : Fin d → ℤ) : Finset (Fin d) :=
  Finset.univ.filter (fun j => k j ≠ 0) -- @realizes k(integer frequency and support)

/-- [ Uniform zero-intercept correctly specified published laws. -/
def frozenUniformClass (d : ℕ) (s : ℝ) : Set (OutcomeLaw d) :=
  {P | covMarginal P = cubeMeasure d ∧ FiniteOutcomeMoments P ∧
    ∃ m : CenteredL2Fn d, SobolevClass d s m ∧ prognosisOf P =ᵐ[cubeMeasure d] m.val}

/-- Canonical main effect, integrating the unused coordinates. -/
def g1 (m : Cube d → ℝ) (j : Fin d) (u : ℝ) : ℝ :=
  ∫ y, m (Function.update y j u) ∂cubeMeasure d -- @realizes g1(canonical marginal integral)

/-- The pre-assignment Gaussian potential-outcome kernel. -/
def gaussianCompletion (m : CenteredL2Fn d) : Kernel (Covariates n d) (Sched n) :=
  ⟨fun x => (noiseLaw n).map (completionSchedule hd m.val x), measurable_completion hd m⟩

/-- Image of the stated Gaussian completion over legal prognostic functions. -/
def gaussianLawClass (d : ℕ) (hd : 0 < d) (s : ℝ) : Set (OutcomeLaw d) :=
  {P | ∃ m : CenteredL2Fn d, SobolevClass d s m ∧ P = gaussianOutcomeLaw hd m}

/-- The Gaussian single-unit completion as a probability law. -/
def gaussianOutcomeLaw {d : ℕ} (hd : 0 < d) (m : CenteredL2Fn d) : OutcomeLaw d :=
  ⟨gaussianOutcomeMeasure hd m, gaussianOutcomeMeasure_probability hd m⟩

/-- Superpopulation target under the Gaussian completion. -/
def gaussianTheta (m : CenteredL2Fn d) : ℝ :=
  ∫ ω, finiteATE ω.2 ∂(covLaw n d ⊗ₘ gaussianCompletion hd m)

/-- Actual unit-weight Horvitz--Thompson ATE estimator. -/
def htEstimator (y : Sched n) (z : Signs n) : ℝ :=
  (2 / (n : ℝ)) * ∑ i, sgn (z i) * (if z i then (y i).2 else (y i).1)

/-- Actual published HT statistic on iid units and original signs. -/
def htPub {n d : ℕ} (ω : (Fin n → Cube d × ℝ × ℝ) × Signs n) : ℝ :=
  htEstimator (fun i => (ω.1 i).2) ω.2

/-- One ordered Gram--Schmidt insertion, discarding zero residuals. -/
def insertOrtho (bs : List (Fin n → ℝ)) (v : Fin n → ℝ) : List (Fin n → ℝ) :=
  let w := removeProjections bs v
  let r := Real.sqrt (rowDot w w)
  if 0 < r then bs ++ [fun i => w i / r] else bs

/-- The reflected covariates, encoded by half of the period-two coordinate. -/
def lift (x : Covariates n d) (η : ReflectionCoins n d) : Fin n → Torus d :=
  fun i j => ((if η i j then (2 - x i j) / 2 else x i j / 2 : ℝ) : UnitAddCircle)

/-- Independent unit-variance Gaussian noise, drawn before assignment. -/
def noiseLaw (n : ℕ) : Measure (Sched n) :=
  Measure.pi (fun _ => (gaussianReal 0 1).prod (gaussianReal 0 1))

/-- Structural ordered Gram--Schmidt; no well-founded recursion enters the algorithm. -/
def orderedOrtho (vs : List (Fin n → ℝ)) : List (Fin n → ℝ) :=
  vs.foldl insertOrtho []

/-- The cutoff's coordinate partial, using the almost-everywhere scalar derivative. -/
-- @node: pairCutoffPartial
def pairCutoffPartial (r : Fin 2) (x : Cube 2) : ℝ :=
  if r = 0 then deriv cosineCutoff (x 0) * cosineCutoff (x 1)
  else cosineCutoff (x 0) * deriv cosineCutoff (x 1)

/-- The prior cutoff. -/
def priorCutoff (n d : ℕ) : ℕ :=
  max 1 ⌈Real.sqrt (4096 * (n : ℝ) / pairCount d)⌉₊ -- @realizes L(positive cutoff ceil √(4096n/B))

/-- The prior average risk, without a measurable-space choice on the function space. -/
def priorRisk (π : Design n d) (s : ℝ) : ℝ≥0∞ :=
  ∑ ξ, (cosinePrior n d s ξ) * loss π (mXi s (priorCutoff n d) ξ)

/-- Potential-outcome midpoint vector. -/
def prognosis (y : Sched n) (i : Fin n) : ℝ :=
  ((y i).2 + (y i).1) / 2 -- @realizes q(schedule midpoint vector)

/-- Conditional midpoint mean, a finite real-valued version modulo covariate null sets. -/
def prognosisOf {d : ℕ} (P : OutcomeLaw d) (u : Cube d) : ℝ :=
  ∫ y, (y.2 + y.1) / 2 ∂P.toMeasure.condKernel u

/-- Actual (real-valued) HT excess above the law's own benchmark. -/
def publishedExcessReal {n d : ℕ} (π : Design n d) (P : OutcomeLaw d) : ℝ :=
  (n : ℝ) * variance htPub (publishedExperiment P π) - VPub P

/-- The complete prognostic image, saturated under Lebesgue null representatives. -/
def publishedPrognosticImage (d : ℕ) (s : ℝ) : Set (Cube d → ℝ) :=
  {f | ∃ P ∈ frozenUniformClass d s, f =ᵐ[cubeMeasure d] prognosisOf P}

/-- Fixed-law worst excess, outside the experiment expectation. -/
def publishedWorst {n d : ℕ} (π : Design n d) (C : Set (OutcomeLaw d)) : ℝ≥0∞ :=
  ⨆ P : C, excess π P.val

