/-- Subtract rank-one projections onto an ordered orthonormal list. -/
def removeProjections (bs : List (Fin n → ℝ)) (v : Fin n → ℝ) : Fin n → ℝ :=
  fun i => v i - (bs.map (fun b => rowDot v b * b i)).sum

