/-- Prefix supplied to the algorithm; rows are numbered starting at one. -/
def rowPrefix (rows : ℕ → Fin n → ℝ) : Fin (n / 4) → Fin n → ℝ :=
  fun h => rows (h.val + 1)

/-- Covariate projection of the iid single-unit sample. -/
def sampleCovariates {n d : ℕ} (xs : Fin n → Cube d × ℝ × ℝ) : Covariates n d :=
  fun i => (xs i).1

/-- Shift the lifted sample by one independent common Haar torus element. -/
def shiftedSample (x : Covariates n d) (η : ReflectionCoins n d) (T : Torus d) :
    Fin n → Torus d := fun i => lift x η i + T

/-- The derivative on reflected open cells has opposite signs on the two halves. -/
-- @node: signedReflectionSlice
def signedReflectionSlice (f' : ℝ → ℂ) (y : ℝ) : ℂ :=
  if y ≤ 1 then f' y else -f' (2 - y)

/-- The outcome class image, saturated under Lebesgue null representatives. -/
def sobolevImage (d : ℕ) (s : ℝ) : Set (Cube d → ℝ) :=
  {f | ∃ m : CenteredL2Fn d, SobolevClass d s m ∧ f =ᵐ[cubeMeasure d] m.val}

/-- Seed image of the prescribed procedure. -/
def spectralRoundingKernel (n d : ℕ) : Kernel (Covariates n d) (Signs n) :=
  ⟨fun x => (spectralSeedLaw n d).map (spectralSigns x), spectralMeasure_measurable n d⟩

/-- Evaluate the first floor(n/4) prescribed real rows at the randomized sample. -/
def spectralRows (w : Fin n → Torus d) : Fin (n / 4) → Fin n → ℝ :=
  fun h i => features d (h.val + 1) (w i)

/-- Independent spectral seed law. -/
def spectralSeedLaw (n d : ℕ) : Measure (SpectralSeeds n d) :=
  (reflectionLaw n d).prod ((torusMeasure d).prod (roundingSeedLaw n))

/-- The prescribed exact-real signing map. -/
def spectralSigns (x : Covariates n d) (seed : SpectralSeeds n d) : Signs n :=
  orderedBoundaryRounding n (spectralRows (shiftedSample x seed.1 seed.2.1)) seed.2.2

/-- The sinusoidal covariate treatment effect. -/
def tauFn (x : Cube d) : ℝ :=
  tau0 + delta * Real.sqrt 2 * Real.sin (2 * Real.pi * x ⟨0, hd⟩)

/-- Fourier characters in L² for the explicitly chosen normalized torus measure. -/
def torusCharacterLp {r : ℕ} (k : Fin r → ℤ) : Lp ℂ 2 (torusMeasure r) :=
  (UnitAddTorus.mFourier k).toLp 2 (torusMeasure r) ℂ

/-- The explicit non-Gaussian completion witness. -/
def twoPointOutcomeLaw (d : ℕ) : OutcomeLaw d :=
  ⟨twoPointOutcomeMeasure d, twoPointOutcomeMeasure_probability d⟩

/-- Worst risk of a specified design. -/
def worstLoss (π : Design n d) (s : ℝ) : ℝ≥0∞ :=
  ⨆ m : {m : CenteredL2Fn d // SobolevClass d s m}, loss π m.val.val
